{
  "directions": [
    {
      "id": "direcao-editorial",
      "title": "Ideias em página",
      "concept": "Uma leitura editorial apresenta o curso como algo que pode tomar forma a partir do conhecimento existente. Papéis organizados sugerem planejamento; o título é a entrada, os blocos seguintes explicam a oferta e o convite encerra a leitura.",
      "composition_plan": {
        "piece_id": "trama-editorial",
        "version": "1",
        "width_px": 1080,
        "height_px": 1080,
        "layers": [
          {"id": "e-fundo", "kind": "shape", "name": "Fundo creme", "shape": "rectangle", "fill_hex": "#F4EBDD", "rect": {"x": 0, "y": 0, "width": 1, "height": 1}, "z_index": 0},
          {"id": "e-imagem", "kind": "image", "name": "Composição de papéis", "asset_ref": "asset-editorial-01", "rect": {"x": 0.55, "y": 0.13, "width": 0.37, "height": 0.37}, "z_index": 1},
          {"id": "e-linha", "kind": "shape", "name": "Linha argila", "shape": "rectangle", "fill_hex": "#C76B4B", "rect": {"x": 0.08, "y": 0.12, "width": 0.12, "height": 0.009}, "z_index": 2},
