          {"id": "e-titulo", "kind": "text", "name": "Chamada principal", "text": "Seu conhecimento\npode virar curso.", "font_ref": "georgia", "font_weight": 700, "font_size_px": 48, "color_hex": "#532B54", "line_height": 1.2, "text_align": "left", "rect": {"x": 0.08, "y": 0.25, "width": 0.48, "height": 0.15}, "z_index": 4},
          {"id": "e-descricao", "kind": "text", "name": "Oferta", "text": "Mentoria online para organizar\nseu primeiro curso curto.", "font_ref": "arial", "font_weight": 400, "font_size_px": 34, "color_hex": "#532B54", "line_height": 1.2, "text_align": "left", "rect": {"x": 0.08, "y": 0.56, "width": 0.84, "height": 0.1}, "z_index": 5},
          {"id": "e-formato", "kind": "text", "name": "Formato", "text": "4 encontros semanais ao vivo\n+ revisão de um plano de aula", "font_ref": "arial", "font_weight": 400, "font_size_px": 30, "color_hex": "#532B54", "line_height": 1.2, "text_align": "left", "rect": {"x": 0.08, "y": 0.7, "width": 0.84, "height": 0.1}, "z_index": 6},
